mapper.select:
SELECT COALESCE(SUM(re.risk_score), 0)
  FROM dcs_risk_event re
 WHERE re.user_id = #{userId}
   AND re.tenant_id = #{tenantId}
   AND re.created_time >= #{startTime}

SELECT COALESCE(SUM(re.risk_score), 0)
  FROM dcs_risk_event re
 WHERE re.ip = #{ip}
   AND re.tenant_id = #{tenantId}
   AND re.created_time >= #{startTime}

SELECT * FROM dcs_risk_event
 WHERE created_time >= #{startTime}
 ORDER BY created_time DESC
 LIMIT #{limit}

SELECT * FROM dcs_risk_event
 WHERE user_id = #{userId}
 ORDER BY created_time DESC
 LIMIT #{limit}
